export function OriginalLightSvg({
  variant,
  height,
  aspectRatio,
  alt,
}: {
  variant: "wordmark" | "full" | "mascot";
  height: string;
  aspectRatio: string;
  alt: string;
}) {
  const html =
    variant === "full"
      ? FULL_LOGO_LIGHT_HTML
      : variant === "mascot"
      ? MASCOT_LIGHT_HTML
      : WORDMARK_LIGHT_HTML;

  return (
    <span
      role="img"
      aria-label={alt}
      className="inline-block shrink-0"
      style={{ height, aspectRatio }}
      dangerouslySetInnerHTML={{ __html: html }}
    />
  );
}
